package cn.sixnine.filmlog;
import android.app.Instrumentation;
import android.content.*;
import android.os.Bundle;
import org.json.*;
import java.util.*;
public final class LegacyRecordsInstrumentation extends Instrumentation {
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){waitForIdleSync();Bundle result=new Bundle();Context c=getTargetContext();SharedPreferences p=Workspace.registry(c);String previous=p.getString("profiles","[]"),active=p.getString("active","guest");try{check(c.getPackageName().equals("cn.sixnine.filmlog.media.tests"),"isolated test package");String first=UUID.randomUUID().toString(),old=UUID.randomUUID().toString();JSONObject profile=new JSONObject().put("workspace",first).put("auth","fixture-opaque-credential").put("previous",new JSONArray().put(new JSONObject().put("workspace",old)));String retained=new JSONArray().put(profile).toString();p.edit().putString("profiles",retained).putString("active","guest").commit();try(LogStore a=new LogStore(new WorkspaceContext(c,first));LogStore b=new LogStore(new WorkspaceContext(c,old))){a.addRoll("retained first","Test","Camera",100,36);b.addRoll("retained old","Test","Camera",400,12);}check(LegacyRecords.available(c)&&LegacyRecords.spaces(c).size()==3,"guest/current/previous namespaces indexed offline");ExposureClock.cancel(Workspace.context(c));ExposureClock.begin(Workspace.context(c),60000);try{LegacyRecords.activate(c,first);throw new AssertionError("switched during active exposure");}catch(IllegalStateException expected){}check(Workspace.current(c).equals("guest"),"running timer preserves active namespace");ExposureClock.cancel(Workspace.context(c));LegacyRecords.activate(c,first);try(LogStore logs=new LogStore(Workspace.context(c))){check(logs.rolls().get(0).name.equals("retained first"),"old main namespace readable");}LegacyRecords.activate(c,old);try(LogStore logs=new LogStore(Workspace.context(c))){check(logs.rolls().get(0).name.equals("retained old"),"old historical namespace readable");}check(p.getString("profiles","").equals(retained),"old profile and opaque credentials untouched");try{LegacyRecords.activate(c,UUID.randomUUID().toString());throw new AssertionError("unindexed namespace accepted");}catch(IllegalArgumentException expected){}check(Workspace.current(c).equals(old),"rejected switch preserves data selection");result.putString("stream","PASS: offline legacy main/history namespaces accessible, running exposure blocks switching, profile/opaque fields unchanged, unknown namespaces refused\n");finish(-1,result);}catch(Throwable error){result.putString("stream",android.util.Log.getStackTraceString(error));finish(1,result);}finally{p.edit().putString("profiles",previous).putString("active",active).commit();}}
}
